	HMODULE FindCda ()
	{
		// The general steps to initializing CDA are as follows:
		// 1. Attempt to access CDA key in the Windows Registry
		// 2. Obtain the "latest" CDA version key in the "0500" family.  This will point to the 
		//    local CDA library location
		// 3. Attempt to load the CDA library
		// 4. Obtain build configuration and version information from the loaded library
		// 5. Call EngineInit to initialize the CDA engine


		CHAR  szDirectory[MAX_PATH+1]   = {0};		
		DWORD dwDirectoryLen			= MAX_PATH;
		CHAR  szLocationKey[MAX_PATH+1] = {0};
		HKEY  hCDAKey					= NULL;	
		DWORD dwType					= 0L;	


		// Retrieve CDA key from the registry
		if( ERROR_SUCCESS != ::RegOpenKeyEx( HKEY_LOCAL_MACHINE, 
											"Software\\WildTangent\\CDA\\", 
											0, 
											KEY_READ, 
											&hCDAKey ) )
		{
			return 0;
		}

		/// Retrieve the latest available CDA version in the "0500" family
		LONG LatestVersion[4] = {0, 5, 0, 0};
		LONG Count = 0;
		for ( ;; )
		{
			::sprintf( szLocationKey, "FileName%d%d%d%d", LatestVersion[0], LatestVersion[1], LatestVersion[2], LatestVersion[3] );
			szLocationKey[MAX_PATH] = '\0';

			// Retrieve path to CDA
			if( ERROR_SUCCESS != ::RegQueryValueEx( hCDAKey,
													szLocationKey, 
													0, 
													&dwType, 
													(BYTE*)szDirectory, 
													&dwDirectoryLen ) )
			{
				if( Count == 0 )
				{
					return 0;
				}
				else
				{	
					::RegCloseKey( hCDAKey );
					hCDAKey = NULL;				
					break;
				}
			}
			else
			{
				Count++;

				::RegCloseKey( hCDAKey );
				hCDAKey = NULL;

				// Attempt to find the next "0500" version available
				// Increment each field and rollover if needed
				LatestVersion[3]++;
				if( LatestVersion[3] > 9 )
				{
					LatestVersion[3] = 0;
					LatestVersion[2]++;
					if( LatestVersion[2] > 9 )
					{
						LatestVersion[2] = 0;
						LatestVersion[1]++;
						if( LatestVersion[1] > 9 )
						{
							LatestVersion[1] = 0;
							LatestVersion[0]++;
							if( LatestVersion[0] > 9 )
							{
								break;
							}
						}
					}
				}
			}
		}

		// Load the CDA library
		const HMODULE Retval = ::LoadLibrary( szDirectory );
		return Retval;
	}
